static void test_basic() {
    Pool p;
    CHECK_EQ(p.size(), 0u);
    CHECK_EQ(p.capacity(), 0u);
    Handle a = p.create("alpha");
    Handle b = p.create("beta");
    Handle c = p.create("gamma");
    CHECK_EQ(a.index, 0);
    CHECK_EQ(a.gen, 1);
    CHECK_EQ(b.index, 1);
    CHECK_EQ(b.gen, 1);
    CHECK_EQ(c.index, 2);
