    CHECK_EQ(p.capacity(), 3u);
    CHECK_EQ(*p.get(a), std::string("alpha"));
    CHECK_EQ(*p.get(c), std::string("gamma"));
    *p.get(b) = "BETA";
    const Pool &cp = p;
    CHECK_EQ(*cp.get(b), std::string("BETA"));
    CHECK(p.alive(a) && p.alive(b) && p.alive(c));
    CHECK(p.destroy(b));
    CHECK(!p.alive(b));
    CHECK(p.get(b) == nullptr);
    CHECK(cp.get(b) == nullptr);
    CHECK(!p.destroy(b));
    CHECK_EQ(p.size(), 2u);
    CHECK_EQ(p.capacity(), 3u);
